-- Real maintained certificate storage shape; real original read/write owners run.
CREATE TABLE IF NOT EXISTS public.accounting_close_certificates(
 kind text NOT NULL CHECK(kind IN('earned_plan','pnl_boundary','pnl_flows','pnl_touched','pnl_clubs')),
 union_id uuid NOT NULL,period_start timestamptz NOT NULL,period_end timestamptz NOT NULL,
 value jsonb NOT NULL,certified_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(kind,union_id,period_start,period_end));
SET LOCAL app.weekly_accounting_chunked='on';
SET LOCAL app.accounting_close_memo='on';
